1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.AddressNormalizer;
13	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
27	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
28	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /** Fixed city-to-region table used to derive an owner's {@code locality}. */
32	    Map<String, String> CITY_REGION = Map.of(
33	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
34	
35	    /**
36	     * Format an owner's stored names as {@code 'LastName, FirstName'} for the
37	     * read-only {@code displayName} field returned on the Owner DTO.
38	     */
39	    default String toDisplayName(Owner owner) {
40	        return owner.getLastName() + ", " + owner.getFirstName();
41	    }
42	
43	    /**
44	     * Build the owner's initials as the upper-cased first letters of firstName and
45	     * lastName, dot-separated with a trailing dot (e.g. {@code 'J.S.'}) for the
46	     * read-only {@code initials} field returned on the Owner DTO.
47	     */
48	    default String toInitials(Owner owner) {
49	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
50	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
51	    }
52	
53	    /**
54	     * Derive the owner's read-only {@code locality}: the canonical region looked up from the
55	     * owner's city in the fixed city-to-region table ({@code Sydney->NSW, Melbourne->VIC,
56	     * Brisbane->QLD}), or {@code 'UNKNOWN'} when the city is not in the table.
57	     */
58	    default String toLocality(Owner owner) {
59	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
60	    }
61	
62	    /**
63	     * Derive the owner's read-only {@code contactPreference}: {@code EMAIL} when the owner has an
64	     * email address, otherwise {@code PHONE}.
65	     */
66	    default OwnerDto.ContactPreferenceEnum toContactPreference(Owner owner) {
67	        return owner.getEmail() != null && !owner.getEmail().isBlank()
68	            ? OwnerDto.ContactPreferenceEnum.EMAIL
69	            : OwnerDto.ContactPreferenceEnum.PHONE;
70	    }
71	
72	    Owner toOwner(OwnerDto ownerDto);
73	
74	    @Mapping(target = "id", ignore = true)
75	    @Mapping(target = "pets", ignore = true)
76	    @Mapping(target = "address", source = "address", qualifiedByName = "normalizeAddress")
77	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
78	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
79	    Owner toOwner(OwnerFieldsDto ownerDto);
80	
81	    /**
82	     * Normalize a postal address to its canonical form (trimmed and whitespace-collapsed,
83	     * upper-cased, with common street-type abbreviations expanded) so it is stored, returned and
84	     * compared in one shape. Blank-after-normalization is rejected separately by
85	     * {@code AddressValidation} on the inbound DTO, so this only performs the transform the stored
86	     * value needs.
87	     */
88	    @Named("normalizeAddress")
89	    default String normalizeAddress(String address) {
90	        return AddressNormalizer.normalize(address);
91	    }
92	
93	    /**
94	     * Normalize a telephone number to canonical E.164 form (a leading {@code '+'}, country
95	     * code and national digits) so it is stored and returned in one comparable form and
96	     * duplicates can be detected by comparing these values. Format validity is enforced
97	     * separately by {@code TelephoneValidation} on the inbound DTO, so this only performs
98	     * the transform the stored value needs.
99	     */
100	    @Named("normalizeTelephone")
101	    default String normalizeTelephone(String telephone) {
102	        return TelephoneNormalizer.toE164(telephone);
103	    }
104	
105	    /**
106	     * Normalize an email address by trimming surrounding whitespace and lower-casing
107	     * it so it is stored and returned in a canonical form. Syntactic validity is
108	     * enforced separately by {@code @Email} on the inbound DTO, so this only performs
109	     * the transform the stored value needs.
110	     */
111	    @Named("normalizeEmail")
112	    default String normalizeEmail(String email) {
113	        return email == null ? null : email.trim().toLowerCase();
114	    }
115	
116	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
117	
118	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
119	
120	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
121	        OwnerPageDto ownerPageDto = new OwnerPageDto();
122	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
123	        ownerPageDto.setPage(ownerPage.getNumber());
124	        ownerPageDto.setSize(ownerPage.getSize());
125	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
126	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
127	        return ownerPageDto;
128	    }
129	}
